using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using Axpense.Api.Data; using Axpense.Api.Domain;
namespace Axpense.Api.Controllers;
[ApiController][Route("api/users")] public class UsersController(AxpenseDbContext db):ControllerBase { [HttpGet] public async Task<IActionResult> Get(Guid organizationId)=>Ok(await db.Users.AsNoTracking().Where(x=>x.OrganizationId==organizationId).Select(x=>new{x.Id,x.FullName,x.Email,x.Role,x.IsActive,x.CreatedAtUtc}).ToListAsync()); [HttpPost] public async Task<IActionResult> Create(CreateUserRequest r){if(!await db.Organizations.AnyAsync(x=>x.Id==r.OrganizationId))return BadRequest("Organization not found.");if(await db.Users.AnyAsync(x=>x.OrganizationId==r.OrganizationId&&x.Email==r.Email))return Conflict("Email already exists in this organization.");var u=new User{OrganizationId=r.OrganizationId,FullName=r.FullName.Trim(),Email=r.Email.Trim().ToLowerInvariant(),PasswordHash=r.PasswordHash,Role=string.IsNullOrWhiteSpace(r.Role)?"User":r.Role};db.Users.Add(u);await db.SaveChangesAsync();return Created($"/api/users/{u.Id}",new{u.Id,u.FullName,u.Email,u.Role});} } public record CreateUserRequest(Guid OrganizationId,string FullName,string Email,string PasswordHash,string? Role);
